import time
def code_B(n):
    for i in range(n): pass
def code_D(n):
    for i in range(n//2):
        for j in range(n//2): pass
for n in [1000,10000]:
    t=time.time(); code_B(n); tb=time.time()-t
    t=time.time(); code_D(n); td=time.time()-t
    print(f'n={n}: B={tb*1e6:.0f}µs D={td*1e6:.0f}µs')

def tri(tab):
    echanges=0
    for i in range(1,len(tab)):
        for j in range(len(tab)-i):
            if tab[j]>tab[j+1]:
                tab[j],tab[j+1]=tab[j+1],tab[j]
                echanges+=1
    return echanges
pire=list(range(10,0,-1))
print('Échanges pire cas n=10:', tri(pire))
